-- Preserve existing product brand labels as company-1 brand records.
INSERT IGNORE INTO `brands` (`company_id`, `name`, `status`, `created_at`, `updated_at`)
SELECT DISTINCT 1, TRIM(`bag_brand`), 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
FROM `master_products` WHERE `bag_brand` IS NOT NULL AND TRIM(`bag_brand`) <> '';
-- Department labels previously mixed company names with warehouse identity.
UPDATE `users` u JOIN `department_options` d ON d.code = u.department
SET u.department = 'overseas_warehouse', u.session_version = u.session_version + 1
WHERE d.name IN ('日本海外仓', '海外仓') AND u.department <> 'overseas_warehouse' AND u.role <> 'system_admin';
UPDATE `users` SET department = 'china_warehouse', session_version = session_version + 1
WHERE department NOT IN ('factory', 'overseas_warehouse', 'china_warehouse') AND role <> 'system_admin';
INSERT INTO `department_options` (`code`,`name`,`status`,`sort`,`created_at`,`updated_at`)
VALUES ('china_warehouse','中国公司人员',1,30,NOW(3),NOW(3)),('overseas_warehouse','日本海外仓',1,20,NOW(3),NOW(3))
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`status`=1;
